const DEADLINE_S = 2700;
const MAX_ATTEMPTS = 40;
const BASE_INTERVAL_S = 65;
const MAX_INTERVAL_S = 120;
const ALLOWED_STATUS_ORIGIN = 'https://replace-with-producer-origin.invalid';

const rawUrl = typeof $json.status_url === 'string' ? $json.status_url : '';
let statusUrl = null;
try {
  const parsed = new URL(rawUrl, ALLOWED_STATUS_ORIGIN);
  const validPath = /^\/api\/v2\/ticket-jobs\/[0-9a-f]{32}$/.test(parsed.pathname);
  if (parsed.origin === ALLOWED_STATUS_ORIGIN && validPath && !parsed.search && !parsed.hash) {
    statusUrl = parsed.toString();
  }
} catch {
  statusUrl = null;
}

const startedAtMs = Date.now();
return {
  json: {
    status_url: statusUrl,
    poll_decision: 'evaluate',
    poll_reason: statusUrl ? 'initialized' : 'invalid_status_url',
    poll_state: {
      started_at_ms: startedAtMs,
      deadline_at_ms: startedAtMs + (DEADLINE_S * 1000),
      attempt: 0,
      next_delay_s: BASE_INTERVAL_S,
      max_attempts: MAX_ATTEMPTS,
      base_interval_s: BASE_INTERVAL_S,
      max_interval_s: MAX_INTERVAL_S
    }
  }
};

const input = $json ?? {};
const state = input.poll_state ?? {};
let decision;
let reason;

if (Date.now() >= state.deadline_at_ms) {
  decision = 'deadline';
  reason = 'deadline_exceeded';
} else if (state.attempt >= state.max_attempts) {
  decision = 'exhausted';
  reason = 'attempts_exhausted';
} else if (!input.status_url) {
  decision = 'fallback';
  reason = 'invalid_status_url';
} else if (input.poll_decision === 'continue') {
  decision = 'wait';
  reason = 'retry_scheduled';
} else {
  decision = 'poll';
  reason = 'poll_allowed';
}

return { json: { ...input, poll_decision: decision, poll_reason: reason } };

const input = $json ?? {};
const state = input.poll_state ?? {};
return {
  json: {
    status_url: input.status_url,
    poll_decision: 'request',
    poll_reason: 'request_started',
    poll_state: { ...state, attempt: state.attempt + 1 }
  }
};

const prior = $('Increment Attempt').item.json;
const statusCode = Number($json.statusCode);
const body = $json.body;
const responseBody = body && typeof body === 'object' && !Array.isArray(body) ? body : null;

return {
  json: {
    status_url: prior.status_url,
    poll_state: prior.poll_state,
    http_status: Number.isInteger(statusCode) ? statusCode : null,
    response_body: responseBody
  }
};

const input = $json ?? {};
const body = input.response_body;
const state = body && typeof body.state === 'string' ? body.state : null;
const inquiries = body && Array.isArray(body.inquiries) ? body.inquiries : [];
const hasManualReview = inquiries.some((item) => item && item.manual_reconciliation_required === true);
const everyReplySafe = inquiries.length > 0 && inquiries.every((item) => item && item.participant_reply_safe === true && item.manual_reconciliation_required !== true);

function projectReply(item) {
  const result = item && item.result && typeof item.result === 'object' ? item.result : null;
  if (!result) return null;

  let replyKind = null;
  let reply = null;
  if (typeof result.needs_more_info_message === 'string' && result.needs_more_info_message.trim()) {
    replyKind = 'needs_more_info';
    reply = result.needs_more_info_message;
  } else if (typeof result.knowledge_answer?.answer === 'string' && result.knowledge_answer.answer.trim()) {
    replyKind = 'knowledge_answer';
    reply = result.knowledge_answer.answer;
  } else {
    const generated = result.generate_response?.response?.response_to_participant;
    if ((typeof generated === 'string' && generated.trim()) || (generated && typeof generated === 'object' && !Array.isArray(generated))) {
      replyKind = 'generated_response';
      reply = generated;
    }
  }

  if (reply === null) return null;
  return { reply_kind: replyKind, reply };
}

const safeReplies = inquiries.map(projectReply).filter((item) => item !== null);
const projectionComplete = safeReplies.length === inquiries.length;
const succeededSafe = state === 'succeeded'
  && body.next_action === 'send_participant_reply'
  && body.metadata?.fallback !== true
  && everyReplySafe
  && !hasManualReview
  && projectionComplete;

let decision = 'fallback';
let reason = 'unexpected_response';
if (hasManualReview) {
  reason = 'manual_reconciliation_required';
} else if (input.http_status === 200 && succeededSafe) {
  decision = 'succeeded';
  reason = 'succeeded_safe';
} else if (input.http_status === 200 && (state === 'queued' || state === 'running')) {
  decision = 'continue';
  reason = state;
} else if (input.http_status === 202 || input.http_status === 429 || (input.http_status >= 500 && input.http_status <= 599)) {
  decision = 'continue';
  reason = 'retryable_http_status';
} else if (input.http_status === 401 || input.http_status === 403) {
  reason = 'access_failure';
} else if (input.http_status === 404 || input.http_status === 410) {
  reason = 'job_not_available';
} else if (input.http_status !== 200) {
  reason = 'poll_http_failure';
} else if (!body) {
  reason = 'invalid_json';
} else if (state === 'succeeded') {
  reason = 'unsafe_succeeded_result';
} else if (['partial', 'failed', 'timeout', 'cancelled'].includes(state)) {
  reason = 'technical_terminal_state';
}

return {
  json: {
    ...input,
    poll_decision: decision,
    poll_reason: reason,
    safe_replies: decision === 'succeeded' ? safeReplies : []
  }
};

const BASE_INTERVAL_S = 65;
const MAX_INTERVAL_S = 120;
const JITTER_RATIO = 0.2;
const input = $json ?? {};
const state = input.poll_state ?? {};
const exponent = Math.max(0, state.attempt - 1);
const rawDelay = Math.min(MAX_INTERVAL_S, BASE_INTERVAL_S * (2 ** exponent));
const deterministicUnit = ((state.attempt * 1103515245 + 12345) >>> 0) / 0xFFFFFFFF;
const jitteredDelay = rawDelay * (1 - JITTER_RATIO + (2 * JITTER_RATIO * deterministicUnit));
const nextDelay = Math.max(BASE_INTERVAL_S, Math.min(MAX_INTERVAL_S, Math.round(jitteredDelay)));

return {
  json: {
    status_url: input.status_url,
    poll_decision: 'wait',
    poll_reason: 'retry_scheduled',
    poll_state: { ...state, next_delay_s: nextDelay }
  }
};

const replies = Array.isArray($json.safe_replies) ? $json.safe_replies : [];
return {
  json: {
    outcome: 'succeeded',
    action: 'publish_participant_reply',
    publishable: replies.length > 0,
    safe_replies: replies
  }
};

const allowedReasons = new Set([
  'invalid_status_url',
  'manual_reconciliation_required',
  'unexpected_response',
  'access_failure',
  'job_not_available',
  'poll_http_failure',
  'invalid_json',
  'unsafe_succeeded_result',
  'technical_terminal_state',
  'request_failed'
]);
const candidate = typeof $json.poll_reason === 'string' ? $json.poll_reason : '';
const reason = allowedReasons.has(candidate) ? candidate : 'poll_failed';
return {
  json: {
    outcome: 'fallback',
    action: 'use_legacy_or_human',
    publishable: false,
    manual_reconciliation_required: reason === 'manual_reconciliation_required',
    reason
  }
};

return {
  json: {
    outcome: 'deadline_exceeded',
    action: 'use_legacy_or_human',
    publishable: false,
    manual_reconciliation_required: true,
    reason: 'deadline_exceeded'
  }
};

return {
  json: {
    outcome: 'attempts_exhausted',
    action: 'use_legacy_or_human',
    publishable: false,
    manual_reconciliation_required: true,
    reason: 'attempts_exhausted'
  }
};
